window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[160]={"id":"160","numero":160,"titre":"Tétanos","objectifs":[{"id":"160-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes du tétanos","contenu":"<p>Le tétanos est une <strong><span class=\"kw-def\">toxi-infection aiguë grave</span></strong> :\n      ce ne sont pas <span class=\"kw-clinique\">les</span> bactéries elles-mêmes mais une <strong><span class=\"kw-def\">neurotoxine</span></strong>\n      qui est responsable des symptômes. La <strong><span class=\"kw-alerte\">mortalité</span></strong> atteint\n      <span class=\"kw-chiffre\">≈ 30 %</span>.</p>\n\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Germe</strong></td>\n            <td><strong><span class=\"kw-etio\">Clostridium tetani</span></strong> : <strong><span class=\"kw-bio\">bacille anaérobie strict</span></strong>,\n            <span class=\"kw-bio\">Gram positif</span>, <strong><span class=\"kw-etio\">tellurique</span></strong>\n            (présent dans la terre, <span class=\"kw-clinique\">les</span> objets souillés, les excréments) ; <span class=\"kw-bio\">forme sporulée résistante</span></td>\n          </tr>\n          <tr>\n            <td><strong>Toxine</strong></td>\n            <td>La <strong><span class=\"kw-def\">tétanospasmine</span></strong>, produite par\n            <span class=\"kw-etio\">C. tetani</span> au niveau de la <span class=\"kw-etio\">plaie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Contagiosité</strong></td>\n            <td>Maladie <strong>non contagieuse</strong> — pas de transmission interhumaine</td>\n          </tr>\n          <tr>\n            <td><strong>Immunité</strong></td>\n            <td>Maladie <strong><span class=\"kw-alerte\">non immunisante</span></strong> : un tétanos déclaré\n            ne protège pas — il faut vacciner le patient au décours</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Mécanisme de la maladie</strong>, étape par étape :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Porte d'entrée cutanée</span></strong> : la toxine est produite dans une\n        <span class=\"kw-etio\">plaie souillée</span>, souvent négligée</li>\n        <li><strong>Cheminement</strong> : la <span class=\"kw-def\">tétanospasmine</span> gagne le\n        <span class=\"kw-def\">système nerveux central</span> via <span class=\"kw-clinique\">les</span> nerfs périphériques\n        (<strong><span class=\"kw-def\">transport rétrograde axonal</span></strong>)</li>\n        <li><strong>Cible</strong> : elle bloque la libération du <strong><span class=\"kw-def\">GABA</span></strong>\n        et de la <strong><span class=\"kw-def\">glycine</span></strong> — <span class=\"kw-clinique\">les</span> deux neurotransmetteurs inhibiteurs</li>\n        <li><strong>Conséquence</strong> : levée de l'inhibition →\n        <strong><span class=\"kw-clinique\">hyperexcitabilité musculaire</span></strong> (contractures, spasmes)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Le tétanos est une maladie <span class=\"kw-alerte\">non immunisante</span> :\n        avoir fait un tétanos ne protège pas d'un second épisode. La <span class=\"kw-ttt\">vaccination</span> est donc\n        <strong>indispensable au décours</strong>, y compris après un tétanos déclaré.\n      </div>","frequence":1},{"id":"160-2","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les modes de contamination du tétanos","contenu":"<p>La contamination se fait toujours par <strong>pénétration de <span class=\"kw-etio\">spores</span> de\n      <span class=\"kw-etio\">C. tetani</span></strong> dans l'organisme. Deux modes principaux :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Effraction cutanéomuqueuse</span></strong> : par une <strong><span class=\"kw-etio\">plaie</span></strong>\n        souillée — <span class=\"kw-etio\">porte d'entrée</span> la plus fréquente</li>\n        <li><strong><span class=\"kw-etio\">Post-partum ou avortement septique</span></strong> : contamination lors de l'accouchement →\n        <strong><span class=\"kw-etio\">tétanos néonatal</span></strong> du nouveau-né (via le <span class=\"kw-etio\">cordon ombilical</span>),\n        dans <span class=\"kw-clinique\">les</span> pays à ressources limitées</li>\n      </ul>\n\n      <p>Le tétanos touche <span class=\"kw-clinique\">les</span> sujets <strong><span class=\"kw-etio\">non ou mal vaccinés</span></strong>. Les populations à risque\n      diffèrent selon le contexte :</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Population à risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pays développés</strong> (tétanos rare en Europe)</td>\n            <td>Surtout <strong><span class=\"kw-clinique\">sujets âgés</span></strong>, avec\n            <strong><span class=\"kw-clinique\">prédominance féminine</span></strong> (femmes historiquement moins bien vaccinées —\n            pas de service militaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Pays à ressources limitées</strong></td>\n            <td><strong><span class=\"kw-clinique\">Nouveau-nés</span></strong> de mère non vaccinée\n            (<span class=\"kw-etio\">tétanos néonatal</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le tétanos n'est <strong><span class=\"kw-etio\">pas contagieux</span></strong> : aucune transmission\n        interhumaine. La contamination est toujours environnementale (<span class=\"kw-etio\">origine tellurique</span>), via une\n        <span class=\"kw-etio\">porte d'entrée cutanéomuqueuse</span>.\n      </div>","frequence":1},{"id":"160-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention du tétanos","contenu":"<p>La prévention combine <strong>la prise en charge de la plaie</strong>, l'<strong>évaluation\n      du statut vaccinal</strong> et la décision <strong>vaccin ± immunoglobulines</strong>.\n      Objectif très tombé à l'EDN.</p>\n\n      <h4>1 · Traitement de la plaie</h4>\n      <ul>\n        <li><strong>Désinfecter</strong> la plaie</li>\n        <li><strong><span class=\"kw-ttt\">Parage</span></strong> : excision des tissus nécrotiques\n        + ablation des corps étrangers</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Devant une plaie tétanigène :\n        <span class=\"kw-ci\">pas de suture</span> tant que le parage n'est pas satisfaisant\n        (corps étrangers résiduels, zones de vitalité douteuses) et\n        <span class=\"kw-ci\">pas de pansement occlusif</span> — l'occlusion favorise l'anaérobiose,\n        donc la germination des spores.\n      </div>\n      <p><span class=\"kw-ttt\">Antibioprophylaxie</span> (selon Asclépia) : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>\n      per os pendant <span class=\"kw-chiffre\">5 jours</span> devant une plaie souillée.</p>\n\n      <h4>2 · Évaluer l'immunisation antérieure</h4>\n      <ul>\n        <li><strong>Carnet de <span class=\"kw-ttt\">vaccination</span></strong> ou autre document médical</li>\n        <li><strong>Tests immunologiques rapides</strong> de détection des <span class=\"kw-bio\">anticorps anti-tétaniques</span> —\n        utilisés aux urgences pour limiter <span class=\"kw-clinique\">les</span> prescriptions inutiles d'immunoglobulines</li>\n      </ul>\n\n      <h4>3 · Vaccin ± séroprophylaxie : décision selon statut vaccinal × type de plaie</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Patient à jour</strong> de ses vaccinations</td>\n            <td><strong>Ni vaccin ni séroprophylaxie</strong> — préciser seulement la date du\n            prochain rappel</td>\n          </tr>\n          <tr>\n            <td><strong>Plaie mineure, propre</strong><br>+ statut incomplet / inconnu</td>\n            <td><span class=\"kw-ttt\">1 dose de vaccin</span> contenant la valence tétanique,\n            immédiatement ; proposer un programme de mise à jour</td>\n          </tr>\n          <tr>\n            <td><strong>Plaie majeure</strong> (étendue, pénétrante, corps étranger, ou traitée\n            tardivement)<br>+ statut non à jour</td>\n            <td><span class=\"kw-ttt\">Dose de vaccin</span> sur un bras <strong>+</strong>\n            <strong>séroprophylaxie</strong> : <span class=\"kw-ttt\">Ig tétaniques humaines</span>\n            <span class=\"kw-chiffre\">250 UI</span> sur l'autre bras ; proposer un programme de mise à jour</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Trismus</span></strong> (fébrile ou non) après plaie\n            souillée = tétanos déclaré</td>\n            <td><span class=\"kw-ttt\">Vaccination + sérothérapie</span> <strong>immédiatement</strong>,\n            sans attendre la confirmation <span class=\"kw-ttt\">biologique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La séroprophylaxie sur plaie majeure couvre le <strong>délai d'apparition des anticorps</strong>\n      après la <span class=\"kw-ttt\">vaccination</span>.</p>\n\n      <h4>4 · <span class=\"kw-ttt\">Calendrier vaccinal</span></h4>\n      <table >\n        <thead><tr><th>Population</th><th>Schéma</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td>Primovaccination à <span class=\"kw-chiffre\">2 mois</span> et <span class=\"kw-chiffre\">4 mois</span> ;\n            rappel à <span class=\"kw-chiffre\">11 mois</span><br>\n            Rappels à <span class=\"kw-chiffre\">6 ans</span> et <span class=\"kw-chiffre\">11-13 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td>Rappels à <span class=\"kw-chiffre\">25 ans</span>, <span class=\"kw-chiffre\">45 ans</span> et\n            <span class=\"kw-chiffre\">65 ans</span>, puis <strong>tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 ans</span> à partir de <span class=\"kw-chiffre\">75 ans</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">dTcaP</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-ttt\">dTP</span></strong> : <span class=\"kw-clinique\">les</span> doses\n      réduites <span class=\"kw-ttt\">dTcaP</span> (avec valence coqueluche) sont utilisées à<span class=\"kw-chiffre\"> 11-13 ans</span>\n      et à<span class=\"kw-chiffre\"> 25 ans</span> ; on passe au <span class=\"kw-ttt\">dTP</span> pour les rappels suivants.</p>\n\n      <h4>5 · Rattrapage de l'adulte non ou mal vacciné</h4>\n      <ul>\n        <li>Schéma en <strong>3 doses</strong> : <span class=\"kw-chiffre\">J0</span>, puis\n        <span class=\"kw-chiffre\">+ 1 mois</span>, puis <span class=\"kw-chiffre\">+ 6 à 12 mois</span></li>\n        <li>Toujours avec un <strong>vaccin combiné</strong> trivalent ou quadrivalent\n        (<span class=\"kw-ttt\">dTP</span> / <span class=\"kw-ttt\">dTcaP</span>) —\n        <span class=\"kw-ci\">jamais de vaccin tétanique seul</span></li>\n      </ul>\n\n      <h4>6 · Sérothérapie (immunoglobulines anti-tétaniques)</h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Immunoglobulines humaines spécifiques anti-tétaniques</span></strong></li>\n        <li>Dose : <span class=\"kw-chiffre\">250 UI</span> en <strong>IM</strong>, en même temps que la\n        1<sup>re</sup> dose vaccinale mais <strong>sur un site différent</strong></li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> La sérothérapie ne se fait <span class=\"kw-ci\">jamais en IV</span>\n        et <span class=\"kw-ci\">jamais mélangée au vaccin</span> : voie IM, site distinct du vaccin\n        (l'autre bras).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":5},{"id":"160-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux signes cliniques devant faire suspecter un tétanos","contenu":"<p>Le diagnostic est <strong>clinique</strong>. Il faut suspecter un tétanos devant l'association\n      <strong><span class=\"kw-etio\">plaie souillée</span> + <span class=\"kw-clinique\">contractures musculaires</span></strong> chez un sujet mal vacciné.</p>\n\n      <h4>Contexte évocateur</h4>\n      <p>Survenue après une <strong><span class=\"kw-etio\">plaie souillée</span></strong> — parfois déjà\n      <strong><span class=\"kw-etio\">cicatrisée</span></strong> au moment de l'examen.</p>\n\n      <h4>Spasmes musculaires (dans l'ordre d'apparition)</h4>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Trismus</span></strong> : <span class=\"kw-clinique\">contraction involontaire et constante\n        des muscles masticateurs</span>, qui diminue ou empêche l'ouverture de la bouche\n        (normalement <span class=\"kw-chiffre\">3 doigts</span>) — c'est le <strong><span class=\"kw-clinique\">premier signe</span></strong></li>\n        <li><strong><span class=\"kw-clinique\">Spasmes généralisés</span></strong> ensuite, par extension</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Signes négatifs discriminants.</strong> Le tétanos est\n        <strong><span class=\"kw-clinique\">non douloureux</span></strong> et\n        <strong><span class=\"kw-clinique\">apyrétique</span></strong> (pas de <span class=\"kw-clinique\">fièvre</span>). Un <span class=\"kw-clinique\">trismus</span> fébrile et\n        douloureux oriente plutôt vers une cause locale (<span class=\"kw-etio\">abcès dentaire</span>, <span class=\"kw-etio\">phlegmon</span>).\n      </div>\n\n      <h4>Formes cliniques à distinguer</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Tétanos généralisé</span></strong><br>(forme typique)</td>\n            <td><span class=\"kw-clinique\">Trismus</span> inaugural, puis <span class=\"kw-clinique\">spasmes diffus</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Tétanos localisé</span></strong></td>\n            <td><span class=\"kw-clinique\">Spasmes limités à un seul groupe musculaire / un seul membre</span> ;\n            <strong><span class=\"kw-clinique\">douloureux mais circonscrits</span></strong> ; <strong><span class=\"kw-clinique\">conscience conservée</span></strong> ;\n            <span class=\"kw-alerte\">pas de trismus</span> ni de raideur généralisée</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Forme céphalique pure</span></strong></td>\n            <td>Atteinte du <span class=\"kw-clinique\">visage</span> et des <span class=\"kw-clinique\">nerfs crâniens</span>, sur <span class=\"kw-etio\">plaie\n            crânienne ou dentaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le <span class=\"kw-clinique\">trismus</span> signe un tétanos\n        <strong>généralisé</strong> : il n'appartient ni à la forme localisée ni à la forme céphalique\n        pure. Et un tétanos localisé peut <strong><span class=\"kw-alerte\">précéder une généralisation</span> dans <span class=\"kw-chiffre\">25 à 50 %</span> des cas</strong>\n        → prise en charge urgente quand même.\n      </div>\n\n      <h4>Paraclinique — Rang C (aucun examen ne doit retarder la prise en charge)</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Prélèvement de la plaie</span> si elle n'est pas cicatrisée</li>\n        <li>Diagnostic <strong>rétrospectif</strong> : <span class=\"kw-bio\">culture</span>, <span class=\"kw-bio\">recherche de la toxine</span> par\n        <span class=\"kw-bio\">PCR</span>, <span class=\"kw-bio\">mise en évidence de l'effet toxinogène par injection à la souris</span></li>\n      </ul>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Tétanos déclaré :</strong> devant un <span class=\"kw-clinique\">trismus</span> (fébrile ou non) après une <span class=\"kw-etio\">plaie souillée</span>, débuter <span class=\"kw-ttt\">vaccination</span> + <span class=\"kw-ttt\">sérothérapie</span> <span class=\"kw-chiffre\">immédiatement</span>, sans attendre la confirmation <span class=\"kw-ttt\">biologique</span>.<br><strong>Plaie à risque :</strong> la décision <span class=\"kw-ttt\">vaccin</span> ± <span class=\"kw-ttt\">immunoglobulines</span> se prend <span class=\"kw-chiffre\">en urgence</span>, en croisant le statut vaccinal et le type de plaie.<br><strong>Paraclinique :</strong> aucun examen (<span class=\"kw-bio\">prélèvement de plaie</span>, <span class=\"kw-bio\">PCR</span>) ne doit retarder la prise en charge.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Trismus</span> après une <span class=\"kw-etio\">plaie souillée</span> = tétanos généralisé déclaré jusqu’à preuve du contraire</li><li><span class=\"kw-alerte\">Spasmes musculaires généralisés</span> faisant suite au <span class=\"kw-clinique\">trismus</span></li><li><span class=\"kw-alerte\">Tétanos localisé</span> (un seul membre) pouvant <span class=\"kw-alerte\">précéder une généralisation</span> dans <span class=\"kw-chiffre\">25 à 50 %</span> des cas → PEC urgente même si localisé</li><li><span class=\"kw-def\">Pronostic</span> sévère : <span class=\"kw-alerte\">mortalité</span> ≈ <span class=\"kw-chiffre\">30 %</span></li></ul>","principes":"<p><strong>Trois temps :</strong> traiter la plaie, évaluer le statut vaccinal, décider <span class=\"kw-ttt\">vaccin</span> ± <span class=\"kw-ttt\">immunoglobulines</span>.</p><p><strong>Traitement de la plaie</strong></p><ul><li>Désinfecter la plaie</li><li><span class=\"kw-ttt\">Parage</span> : excision des tissus nécrotiques + ablation des corps étrangers</li><li><span class=\"kw-ci\">Pas de suture</span> tant que le parage n’est pas satisfaisant</li><li><span class=\"kw-ci\">Pas de pansement occlusif</span> (favorise l’anaérobiose et la germination des spores)</li><li><span class=\"kw-ttt\">Antibioprophylaxie</span> (Asclépia) : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> per os <span class=\"kw-chiffre\">5 jours</span> si plaie souillée</li></ul><p><strong>Évaluer le statut vaccinal</strong></p><ul><li><span class=\"kw-bio\">Carnet de vaccination</span> ou autre document médical</li><li><span class=\"kw-bio\">Tests immunologiques rapides</span> de détection des AC anti-tétaniques aux urgences (limitent <span class=\"kw-clinique\">les</span> prescriptions inutiles d’Ig)</li></ul><p><strong>Vaccin ± immunoglobulines (statut × plaie)</strong></p><ul><li><strong>Patient à jour</strong> : <span class=\"kw-ci\">ni vaccin ni séroprophylaxie</span>, préciser la date du prochain rappel</li><li><strong>Plaie mineure, propre</strong> + statut incomplet / inconnu : <span class=\"kw-ttt\">1 dose de vaccin</span> + programme de mise à jour</li><li><strong>Plaie majeure</strong> (étendue, pénétrante, corps étranger, traitée tardivement) + statut non à jour : <span class=\"kw-ttt\">vaccin</span> sur un bras + <span class=\"kw-ttt\">Ig tétaniques humaines</span> <span class=\"kw-chiffre\">250 UI</span> sur l’autre bras</li><li><strong>Tétanos déclaré</strong> : <span class=\"kw-ttt\">vaccination + sérothérapie</span> <span class=\"kw-chiffre\">immédiatement</span></li></ul><p><strong>Sérothérapie (immunoglobulines)</strong></p><ul><li><span class=\"kw-ttt\">Immunoglobulines humaines spécifiques anti-tétaniques</span> <span class=\"kw-chiffre\">250 UI</span> en IM</li><li>En même temps que la 1<sup>re</sup> dose vaccinale, mais sur un site différent (l’autre bras)</li><li><span class=\"kw-ci\">Jamais en IV</span>, <span class=\"kw-ci\">jamais mélangée au vaccin</span></li></ul><p><strong>Calendrier & rattrapage vaccinal</strong></p><ul><li>Enfant : <span class=\"kw-chiffre\">2 mois</span>, <span class=\"kw-chiffre\">4 mois</span>, rappel <span class=\"kw-chiffre\">11 mois</span> ; rappels <span class=\"kw-chiffre\">6 ans</span> et <span class=\"kw-chiffre\">11-13 ans</span></li><li>Adulte : rappels <span class=\"kw-chiffre\">25 ans</span>, <span class=\"kw-chiffre\">45 ans</span>, <span class=\"kw-chiffre\">65 ans</span>, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 ans</span> dès <span class=\"kw-chiffre\">75 ans</span></li><li>Rattrapage adulte non / mal vacciné : <span class=\"kw-chiffre\">J0</span> – <span class=\"kw-chiffre\">+1 mois</span> – <span class=\"kw-chiffre\">+6 à 12 mois</span></li><li>Toujours un <span class=\"kw-ttt\">vaccin combiné</span> (<span class=\"kw-ttt\">dTP</span> / <span class=\"kw-ttt\">dTcaP</span>), <span class=\"kw-ci\">jamais de vaccin tétanique seul</span></li></ul>","suivi":"<p><strong>Maladie non immunisante :</strong> un tétanos déclaré ne protège pas d’une récidive → <span class=\"kw-ttt\">vacciner</span> le patient au décours.<br><strong><span class=\"kw-def\">Surveillance</span> :</strong> un <span class=\"kw-clinique\">tétanos localisé</span> peut se généraliser → surveillance rapprochée.<br><strong>Mise à jour :</strong> proposer systématiquement un <span class=\"kw-ttt\">programme de rattrapage</span> si le statut vaccinal est incomplet.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-160.pdf","label":"Collège Pilly — Tétanos (item 160, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient consultant pour une plaie — Évaluer le risque tétanigène","detail":"<h4>CAT — Plaie à risque tétanigène — Croiser statut vaccinal × type de plaie ; reconnaître le tétanos déclaré</h4>","branches":[{"to":"t-declare","label":"Trismus / spasmes après plaie souillée","color":"red"},{"to":"q-statut","label":"Plaie sans signe de tétanos","color":"green"}]},{"id":"t-declare","kind":"terminal","label":"Tétanos déclaré","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Trismus</span> (fébrile ou non) après une <span class=\"kw-etio\">plaie souillée</span></li><li><span class=\"kw-clinique\">Spasmes musculaires généralisés</span> secondaires</li><li>Maladie <span class=\"kw-clinique\">non douloureuse</span> et <span class=\"kw-clinique\">apyrétique</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination</span> + <span class=\"kw-ttt\">sérothérapie</span> <span class=\"kw-chiffre\">immédiatement</span>, sans attendre la confirmation <span class=\"kw-ttt\">biologique</span></li><li>Nettoyage et <span class=\"kw-ttt\">parage</span> soigneux de la plaie</li><li>± <span class=\"kw-ttt\">métronidazole</span> (<span class=\"kw-ttt\">antibiothérapie</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Risque de généralisation</span> ; <span class=\"kw-def\">pronostic</span> sévère (<span class=\"kw-alerte\">mortalité</span> ≈ <span class=\"kw-chiffre\">30 %</span>) ; maladie <span class=\"kw-alerte\">non immunisante</span> → poursuivre la <span class=\"kw-ttt\">vaccination</span></li></ul>"},{"id":"q-statut","kind":"decision","label":"Statut vaccinal antitétanique à jour ?","branches":[{"to":"t-ajour","label":"À jour","color":"green"},{"to":"q-plaie","label":"Incomplet / inconnu","color":"amber"}]},{"id":"t-ajour","kind":"terminal","label":"Patient à jour de ses vaccinations","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ci\">Ni vaccin ni séroprophylaxie</span> — préciser seulement la date du prochain rappel</li></ul><h4>Plaie</h4><ul><li>Soins locaux : désinfection, <span class=\"kw-ttt\">parage</span> si nécessaire</li></ul>"},{"id":"q-plaie","kind":"decision","label":"Type de plaie ?","branches":[{"to":"t-mineure","label":"Mineure, propre","color":"amber"},{"to":"t-majeure","label":"Majeure / souillée","color":"amber"}]},{"id":"t-mineure","kind":"terminal","label":"Plaie mineure propre","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">1 dose de vaccin</span> contenant la valence tétanique, immédiatement</li></ul><h4>Conduite</h4><ul><li>Proposer un <span class=\"kw-ttt\">programme de mise à jour</span> vaccinale (<span class=\"kw-chiffre\">J0</span> – <span class=\"kw-chiffre\">+1 mois</span> – <span class=\"kw-chiffre\">+6 à 12 mois</span>)</li></ul>"},{"id":"t-majeure","kind":"terminal","label":"Plaie majeure ou souillée — Étendue, pénétrante, corps étranger ou traitée tardivement","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dose de vaccin</span> sur un bras</li><li><span class=\"kw-ttt\">Ig tétaniques humaines</span> <span class=\"kw-chiffre\">250 UI</span> en IM sur l’autre bras (couvre le délai d’apparition des anticorps)</li><li>Soins de plaie : <span class=\"kw-ttt\">parage</span>, <span class=\"kw-ci\">pas de suture</span> ni de <span class=\"kw-ci\">pansement occlusif</span></li></ul><h4>Conduite</h4><ul><li>Proposer un <span class=\"kw-ttt\">programme de mise à jour</span> vaccinale</li></ul>"}]},"cards":[]};